import { sha256 } from "../config/hash.js";

// First line of every generated file. The hash covers the body (everything after this line), so `cli` can tell
// an unedited file from a hand-edited one even after a config change rewrites the body.
const MARKER = /^<!-- generated by liftoff render ([^\s;]+); body-sha256:([0-9a-f]{64}); edit AGENTS\.md instead -->$/;

// BOM stripped, CRLF to LF: what a file looks like regardless of the platform's checkout settings.
export const normalizeEol = (text: string): string => text.replace(/^﻿/, "").replace(/\r\n/g, "\n");

export const bodyHash = (body: string): string => sha256(normalizeEol(body)).slice("sha256:".length);

export const withMarker = (generatorVersion: string, body: string): string =>
  `<!-- generated by liftoff render ${generatorVersion}; body-sha256:${bodyHash(body)}; edit AGENTS.md instead -->\n${body}`;

export interface Marker {
  version: string;
  hash: string;
  body: string; // LF-normalized
}

export function parseMarker(text: string): Marker | undefined {
  const t = normalizeEol(text);
  const newline = t.indexOf("\n");
  const match = MARKER.exec(newline === -1 ? t : t.slice(0, newline));
  if (!match) return undefined;
  return { version: match[1]!, hash: match[2]!, body: newline === -1 ? "" : t.slice(newline + 1) };
}

// Marker present and the body still hashes to what the marker says.
export function isUnedited(text: string): boolean {
  const marker = parseMarker(text);
  return marker !== undefined && bodyHash(marker.body) === marker.hash;
}
